/** (A) Urut A-Z/Z-A daftar siswa pada modal absen masal (DOM reorder — pilihan radio aman). */
let urutNamaModalAsc = null; // null = urutan asli (belum diurutkan)
function toggleUrutNamaModal() {
  urutNamaModalAsc = !(urutNamaModalAsc === true);
  const c = document.getElementById('daftar-siswa-modal');
  if (!c) return;
  [...c.children].sort((a, b) => {
    const ta = ((a.querySelector('.modal-nama-absen')?.innerText || '').trim()).replace(/^\d+\.\s*/, '');
    const tb = ((b.querySelector('.modal-nama-absen')?.innerText || '').trim()).replace(/^\d+\.\s*/, '');
    return urutNamaModalAsc ? ta.localeCompare(tb, 'id', { sensitivity: 'base' }) : tb.localeCompare(ta, 'id', { sensitivity: 'base' });
  }).forEach(n => c.appendChild(n));
  const btn = document.getElementById('btn-urut-nama-modal');
  if (btn) btn.innerHTML = urutNamaModalAsc ? '<i class="fa-solid fa-arrow-down-a-z"></i> A-Z' : '<i class="fa-solid fa-arrow-up-a-z"></i> Z-A';
}

/** Parse input hari bebas: "1, 3-5, 8 dan 10" / "1 sampai 3" → [1,3,4,5,8,10]. */
function parseDaftarHari(input) {
  const hari = new Set();
  const norm = String(input || '').toLowerCase()
    .replace(/\bsampai\b|\bs\/d\b|\bantara\b|\b-\b/g, '-')
    .replace(/\bdan\b|&/g, ',')
    .replace(/[^0-9,\-]/g, ',');
  norm.split(',').forEach(part => {
    const p = part.trim();
    if (!p) return;
    const m = p.match(/^(\d+)\s*-\s*(\d+)$/);
    if (m) { for (let i = Math.min(+m[1], +m[2]); i <= Math.max(+m[1], +m[2]); i++) hari.add(i); }
    else if (/^\d+$/.test(p)) hari.add(parseInt(p, 10));
  });
  return [...hari].filter(h => h >= 1 && h <= 31).sort((a, b) => a - b);
}

/** Cache guru → peta wali kelas (nama bergelar). */
let cacheGuruWali = [];

// ---------- DATA EKSTRAKURIKULER (SHARED) ----------
let cacheEkstrakurikuler = [];

/** Daftar ekskul gabungan (tabel ekstrakurikuler + Master Data), A-Z; baris tabel dicache di cacheEkstrakurikuler. */
async function ambilDaftarEkskul() {
  let dariTabel = [];
  try {
    const { data, error } = await supaClient.from('ekstrakurikuler').select('*');
    if (!error && data) {
      cacheEkstrakurikuler = data;
      dariTabel = data.map(e => e.nama_ekskul).filter(Boolean);
    }
  } catch (e) { console.warn('ambilDaftarEkskul:', e); }
  const dariMaster = [...new Set((masterDataCache || []).map(m => m["Ekstrakurikuler"]).filter(Boolean))];
  return urutAz([...new Set([...dariTabel, ...dariMaster])]);
}

/** Anggota ekskul: murid (tabel akun) yang kolom Ekstrakurikuler-nya memuat ekskul terpilih. */
async function ambilAnggotaEkskul(ekskul) {
  if (!ekskul) return [];
  const kolom = 'nis_nip, nama_lengkap, tingkat_kelas, jabatan, no_telepon, jabatan_ekskul_map';
  let { data, error } = await supaClient.from('akun')
    .select(kolom)
    .eq('tipe', 'murid')
    .ilike('ekstrakurikuler', `%${ekskul}%`);
  // Kolom jabatan_ekskul_map belum ada (migrasi 20260926 belum dijalankan) → coba tanpa kolom itu
  if (error && /jabatan_ekskul_map/i.test(error.message || '')) {
    ({ data, error } = await supaClient.from('akun')
      .select('nis_nip, nama_lengkap, tingkat_kelas, jabatan, no_telepon')
      .eq('tipe', 'murid')
      .ilike('ekstrakurikuler', `%${ekskul}%`));
  }
  if (error) { console.warn('ambilAnggotaEkskul:', error); return []; }
  return data || [];
}

/** [REQ 1a] Peta jabatan ekskul anggota: nis → jabatan (dari kolom akun.jabatan_ekskul_map[ekskul]). */
function petaJabatanAnggota(ekskul, anggota) {
  const map = {};
  (anggota || []).forEach(a => {
    const m = a && a.jabatan_ekskul_map;
    const jab = (m && typeof m === 'object') ? String(m[ekskul] || '').trim() : '';
    if (jab) map[String(a.nis_nip)] = jab;
  });
  return map;
}
async function petaWaliKelas() {
  if (cacheGuruWali.length === 0) {
    try {
      const { data, error } = await supaClient.from('akun')
        .select('nama_lengkap, gelar_depan, gelar_belakang, wali_kelas')
        .in('tipe', ['guru', 'admin']);
      if (!error && data) cacheGuruWali = data;
    } catch (e) { console.warn('petaWaliKelas:', e); }
  }
  const map = {};
  (cacheGuruWali || []).forEach(g => {
    if (g.wali_kelas) map[g.wali_kelas] = [g.gelar_depan, g.nama_lengkap, g.gelar_belakang].filter(Boolean).join(' ').replace(' ,', ', ');
  });
  return map;
}
